import React, { useState } from 'react';
import {
  DataTable,
  TableContainer,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
  TableSelectAll,
  TableSelectRow,
  TableBatchActions,
  TableBatchAction,
  Button,
} from '@carbon/react';
import Download16 from '@carbon/icons-react/lib/download/16';
import Delete16 from '@carbon/icons-react/lib/delete/16';

// Generate a large set of rows for demonstration (e.g. 1,228 total)
const totalRows = Array.from({ length: 1228 }, (_, i) => ({
  id: String(i + 1),
  name: `Item ${i + 1}`,
  description: `Description for item ${i + 1}`,
}));

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'description', header: 'Description' },
];

function App() {
  // Simulate paginated rows: only first 50 show on page
  const [pageSize] = useState(50);
  const currentPageRows = totalRows.slice(0, pageSize);

  return (
    <DataTable rows={currentPageRows} headers={headers} isSortable>
      {({
        rows,
        headers,
        getTableProps,
        getHeaderProps,
        getRowProps,
        getSelectionProps,
        getBatchActionsProps,
        selectedRows,
        selectAll,
      }) => (
        <TableContainer title="My table">
          {/* Batch actions bar with custom Select all button */}
          <TableBatchActions {...getBatchActionsProps()}>
            <span>{selectedRows.length} items selected</span>
            {/* the new button next to the count */}
            <Button
              kind="ghost"
              size="sm"
              onClick={() => selectAll()}
              style={{ marginLeft: '1rem' }}
            >
              Select all ({totalRows.length})
            </Button>
            {/* example default batch actions */}
            <TableBatchAction renderIcon={Download16} onClick={() => console.log('Download')}>
              Download
            </TableBatchAction>
            <TableBatchAction renderIcon={Delete16} onClick={() => console.log('Delete')}>
              Delete
            </TableBatchAction>
          </TableBatchActions>

          {/* The table with row selection checkboxes */}
          <Table {...getTableProps()}>
            <TableHead>
              <TableRow>
                <TableSelectAll {...getSelectionProps()} />
                {headers.map(header => (
                  <TableHeader key={header.key} {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(row => (
                <TableRow key={row.id} {...getRowProps({ row })}>
                  <TableSelectRow {...getSelectionProps({ row })} />
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </DataTable>
  );
}

export default App;
